import {ChartCard} from '@github-ui/chart-card'
import {getTickPositions, tooltipFormatter} from './utils/Utility'
import ChartErrorState from './ChartErrorState'

interface StackedAreaChartData {
  id: string
  label: string
  startDate: string
  endDate: string
  values: Array<{
    name: string
    percentage: number
  }>
}

interface StackedAreaChartPayload {
  startDate: string
  endDate: string
  data: StackedAreaChartData[]
}

interface StackedAreaChartProps {
  payload: StackedAreaChartPayload
  title: string
  description?: string
  yAxisTitle?: string
}

const lineColors = ['blue', 'indigo', 'green', 'teal', 'orange']
const lineStyles = ['Dot', 'DotDash', 'Solid', 'ShortDash', 'LongDash']

function StackedAreaChart({payload, title, description, yAxisTitle}: StackedAreaChartProps) {
  if (!payload.data || payload.data.length === 0) {
    return <ChartErrorState title={title} description={description} />
  }

  const seriesNames = payload.data[0]?.values?.map(v => v.name) || []
  const reversedSeriesNames = [...seriesNames].reverse()
  const series = reversedSeriesNames.map(modelName => ({
    name: modelName,
    data: payload.data.map(item => {
      const modelData = item.values.find(v => v.name === modelName)
      return [new Date(item.endDate).getTime(), modelData?.percentage ?? 0]
    }),
    type: 'areaspline',
    color: lineColors[seriesNames.indexOf(modelName) % lineColors.length],
    dashStyle: lineStyles[seriesNames.indexOf(modelName) % lineStyles.length],
  }))

  return (
    <div>
      <ChartCard size="medium" border padding="normal" visibleControls={false} className="width-full">
        <ChartCard.Title as="h2">{title}</ChartCard.Title>
        {description && <ChartCard.Description>{description}</ChartCard.Description>}
        <ChartCard.Chart
          useUTC
          yAxisTitle={yAxisTitle ?? ''}
          series={series}
          xAxisOptions={{
            type: 'datetime',
            lineWidth: 1,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
            labels: {
              format: '{value:%b %d}',
            },
            minPadding: 0,
            maxPadding: 0,
            tickPositions: getTickPositions(payload.data, 'auto'),
          }}
          yAxisOptions={{
            min: 0,
            max: 100,
            gridLineWidth: 1,
            gridLineDashStyle: 'Solid',
          }}
          type="areaspline"
          plotOptions={{
            areaspline: {
              stacking: 'normal',
              marker: {
                enabled: false,
              },
            },
          }}
          overrideOptionsNotRecommended={{
            accessibility: {
              landmarkVerbosity: 'one',
              series: {
                describeSingleSeries: true,
              },
            },
            legend: {
              align: 'left',
              verticalAlign: 'top',
              layout: 'horizontal',
              reversed: true,
              alignColumns: false,
            },
            chart: {
              spacingRight: 2,
            },
          }}
          tooltipOptions={{
            shared: true,
            outside: true,
            formatter: tooltipFormatter(yAxisTitle?.toLowerCase()),
            useHTML: true,
          }}
        />
      </ChartCard>
    </div>
  )
}

export default StackedAreaChart

try{ StackedAreaChart.displayName ||= 'StackedAreaChart' } catch {}